import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import './AdvertisementDetail.css';

const AdvertisementDetail = () => {
  const { id } = useParams();
  const [ad, setAd] = useState(null);
  const [formData, setFormData] = useState({ name: '', email: '' });
  const [submitted, setSubmitted] = useState(false);

  useEffect(() => {
    fetch(`http://localhost:5000/advertisements/${id}`)
      .then(res => res.json())
      .then(data => setAd(data))
      .catch(console.error);
  }, [id]);

  const handleChange = e => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = e => {
    e.preventDefault();
    // Here put your registration form submission logic, e.g., API call
    console.log('Registration data:', formData);
    setSubmitted(true);
  };

  if (!ad) return <div>Loading...</div>;

  return (
    <div className="ad-detail-container">
        
      <h2>{ad.title}</h2>
      <img src={ad.imageUrl} alt={ad.title} className="ad-detail-image" />
      <p>{ad.description}</p>

      {submitted ? (
        <p>Thank you for registering!</p>
      ) : (
        <form onSubmit={handleSubmit} className="registration-form">
          <h3>Register Here</h3>
          <input
            required
            type="text"
            name="name"
            placeholder="Your Name"
            value={formData.name}
            onChange={handleChange}
          />
          <input
            required
            type="email"
            name="email"
            placeholder="Your Email"
            value={formData.email}
            onChange={handleChange}
          />
          <button type="submit">Submit</button>
        </form>
      )}
    </div>
  );
};

export default AdvertisementDetail;
